//`timescale 1 ns / 1 ps
module RS_dec_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;


parameter pclk = 5;     /// period of clk/2 

parameter number = 100;  ///  number of input codewords


reg clk,reset;
reg instrumented_clk;
reg CE;
reg [7:0] input_byte;

wire [7:0] Out_byte;
wire CEO;
wire Valid_out;

integer f;
string path;

RS_dec  DUT 
(
  .clk(clk), // input clock 
  .reset(reset), // active high asynchronous reset
  .CE(CE), // chip enable active high flag for one clock with every input byte
  .input_byte(input_byte), // input byte

  .Out_byte(Out_byte),   // output byte
  .CEO(CEO),  // chip enable for the next block will be active high for one clock , every 8 clks
  .Valid_out(Valid_out) /// valid out for every output block (188 byte)
);

reg [7:0] in_mem [0:(number*204)-1];
reg [7:0] out_mem [0:(number*188)-1];

reg enable;
reg [7:0]true_out;
integer h,k,err;

always #(pclk*4) instrumented_clk=~instrumented_clk; // this is 2*clk

initial begin
	clk=0;
	instrumented_clk=0;
	forever 
		#pclk clk=~clk;
end 

initial begin
	f = $fopen("output_RS_dec_tb_t1.txt");
	$fwrite(f, "time,Out_byte[7],Out_byte[6],Out_byte[5],Out_byte[4],Out_byte[3],Out_byte[2],Out_byte[1],Out_byte[0],CEO,Valid_out\n");
	 $fwrite(f, "%0d,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b\n",
		 $time,Out_byte[7],Out_byte[6],Out_byte[5],Out_byte[4],Out_byte[3],Out_byte[2],Out_byte[1],Out_byte[0],CEO,Valid_out);
	forever begin
		//@(posedge clk);
		//#5
		#1
		$fwrite(f, "%0d,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b\n",
		$time,Out_byte[7],Out_byte[6],Out_byte[5],Out_byte[4],Out_byte[3],Out_byte[2],Out_byte[1],Out_byte[0],CEO,Valid_out);
	end
end

// initial begin
    // wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

// #2661585
// $finish;
// end


integer ce_t,in_t;
integer lim; // minimum  6

initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

	err=0;
	lim=6;
	// Note: Change the path to point to the right directory if there is a file not found error
	path="./";
	$readmemb({path,"input_RS_blocks"}, in_mem);
	$readmemb({path,"output_RS_blocks"}, out_mem);
end


initial begin
	CE=0;
	@(posedge enable);
	forever
	begin
		@(posedge clk);
		#2 CE=1;
		@(posedge clk);
		#2 CE=0;
		for(ce_t=0; ce_t<lim; ce_t=ce_t+1)
			@(posedge clk); 
	end 
end

initial begin
	h=0;
	k=0;
	enable = 0;
	reset =1;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

	@(posedge clk); @(posedge clk); @(posedge clk);
	@(posedge clk); @(posedge clk); @(posedge clk);
	reset=0;
	@(posedge clk); @(posedge clk);
	enable=1;
end


///////////////////// inputs///////////////

initial begin

	input_byte=0;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB


	@(posedge enable);

	for(k=0;k<(number*204);k=k+1)
	begin

		input_byte=in_mem[k];

		@(posedge clk);@(posedge clk);
		for(in_t=0; in_t < lim; in_t=in_t+1)
			@(posedge clk); 
	end 

end

//////////////////////////////outputs////////////////////////
always @ (posedge(clk))
begin
	if(Valid_out && CEO)
		begin
			true_out = out_mem[h];

			if(true_out !== Out_byte)
				begin
					//$display("Error at out no. %d !!!!!!!!!!!!!",h);
					err=err+1;
				end
			h=h+1;

			if(h == (number*188) )
				begin
					if (err == 0)
						$display("No Errors !!!!!!!!!!!!!");
					else
						$display("Total Errors =  %d !!!!!!!!!!!!!",err);
					$finish;
				end

		end
end
  initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

#2000000
$finish;
end


// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1'b1);

    $display("LLM Phase: Starting Mutation Testing Stimuli...");

    // Initialize inputs
    reset = 1;
    CE = 0;
    input_byte = 8'h00;

    // Reset sequence
    repeat(10) @(posedge clk);
    reset = 0;
    repeat(10) @(posedge clk);

    // -------------------------------------------------------
    // Test Case 1: All Zeros (Baseline)
    // -------------------------------------------------------
    // Purpose: Verify pipeline with clean data (0 errors).
    // Expected: Output should be all zeros.
    for (i = 0; i < 204; i = i + 1) begin
        @(posedge clk);
        #2;
        CE = 1;
        input_byte = 8'h00;
        @(posedge clk);
        #2;
        CE = 0;
        // Maintain 8-clock period (1 active + 7 idle)
        repeat(6) @(posedge clk);
    end

    // Wait for processing latency (approx 500-600 clocks)
    repeat(600) @(posedge clk);

    // -------------------------------------------------------
    // Test Case 2: Single Bit Error at Start (Byte 0)
    // -------------------------------------------------------
    // Purpose: Test error detection/correction on the first byte.
    // Byte 0 = 0x01, Rest = 0x00.

    // Byte 0
    @(posedge clk);
    #2;
    CE = 1;
    input_byte = 8'h01; // Inject Error
    @(posedge clk);
    #2;
    CE = 0;
    repeat(6) @(posedge clk);

    // Bytes 1-203
    for (i = 1; i < 204; i = i + 1) begin
        @(posedge clk);
        #2;
        CE = 1;
        input_byte = 8'h00;
        @(posedge clk);
        #2;
        CE = 0;
        repeat(6) @(posedge clk);
    end

    repeat(600) @(posedge clk);

    // -------------------------------------------------------
    // Test Case 3: Single Bit Error at End (Byte 203)
    // -------------------------------------------------------
    // Purpose: Test error detection/correction on the last byte (parity/data boundary).

    // Bytes 0-202
    for (i = 0; i < 203; i = i + 1) begin
        @(posedge clk);
        #2;
        CE = 1;
        input_byte = 8'h00;
        @(posedge clk);
        #2;
        CE = 0;
        repeat(6) @(posedge clk);
    end

    // Byte 203
    @(posedge clk);
    #2;
    CE = 1;
    input_byte = 8'h01; // Inject Error
    @(posedge clk);
    #2;
    CE = 0;
    repeat(6) @(posedge clk);

    repeat(600) @(posedge clk);

    // -------------------------------------------------------
    // Test Case 4: Alternating Pattern (0x55/0xAA)
    // -------------------------------------------------------
    // Purpose: Stress test bit-level logic in syndrome calculation.
    // Send 10 bytes of pattern, then 0s.
    for (i = 0; i < 204; i = i + 1) begin
        @(posedge clk);
        #2;
        CE = 1;
        if (i < 10) begin
            if ((i & 1) == 0) input_byte = 8'h55;
            else input_byte = 8'hAA;
        end else begin
            input_byte = 8'h00;
        end
        @(posedge clk);
        #2;
        CE = 0;
        repeat(6) @(posedge clk);
    end

    repeat(600) @(posedge clk);

    // -------------------------------------------------------
    // Test Case 5: Boundary Value (0xFF)
    // -------------------------------------------------------
    // Purpose: Test handling of all-ones byte (max value).
    // Byte 5 is 0xFF, rest 0.
    for (i = 0; i < 204; i = i + 1) begin
        @(posedge clk);
        #2;
        CE = 1;
        if (i == 5) input_byte = 8'hFF;
        else input_byte = 8'h00;
        @(posedge clk);
        #2;
        CE = 0;
        repeat(6) @(posedge clk);
    end

    repeat(600) @(posedge clk);

    // 3. Handover
    $display("LLM Phase Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #2000000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (f != 0) $fclose(f);
    $finish;
end

endmodule

