          W_Add2 <= Address_error_correction;
          W_Add1 <= 0;
          input_byte2 <= correction_value;
          input_byte1 <= 0;
        end
      end
    end
  end


  always @(posedge clk or posedge reset) begin
    if(reset) begin
      RE1 <= 0;
      RE2 <= 0;
      R_Add1 <= 0;
      R_Add2 <= 0;
      initial_value <= 0;
