      end 
      if(DONE) out_flag <= 1; 
      if(out_done && !DONE_ext && !DONE) out_flag <= 0; 
      if(DONE && out_flag && !out_done) DONE_ext <= 1; 
      if(out_done) DONE_ext <= 0; 
      case(state)
        state1: begin
          if(S_ready) begin
            S_flag <= 1;
            state <= state2;
          end 
        end
        state2: begin
          if(L_ready) begin
            S_flag <= 0;
            L_flag <= 1;
            state <= state3;
          end 
        end
        state3: begin
          if(roots_ready) begin
            L_flag <= 0;
            R_flag <= 1;
            state <= state4;
          end 
        end
        default: begin
          if(DONE) begin
            R_flag <= 0;
            state <= state1;
          end 
        end
      endcase
    end
  end

  wire [2:0] control;
  assign control = { R_flag, L_flag, S_flag };

  always @(*) begin
    add_pow1 <= 0;
    add_pow2 <= 0;
