  reg S_flag;reg L_flag;reg R_flag;reg T_flag;reg out_flag;
  parameter state1 = 6'b000001;
  parameter state2 = 6'b000010;
  parameter state3 = 6'b000100;
  parameter state4 = 6'b001000;
  parameter state5 = 6'b010000;
  parameter state6 = 6'b100000;
  reg [5:0] state = state1;

  always @(posedge clk or posedge reset) begin
    if(reset) begin
      S_flag <= 0;
      L_flag <= 0;
      R_flag <= 0;
      T_flag <= 0;
      out_flag <= 0;
      DONE_ext <= 0;
      state <= state1;
    end else begin
      if(S_ready) begin
        T_flag <= 1;
      end 
      if(transport_done) begin
        T_flag <= 0;
      end 
      if(DONE) out_flag <= 1; 
      if(out_done && !DONE_ext && !DONE) out_flag <= 0; 
      if(DONE && out_flag && !out_done) DONE_ext <= 1; 
      if(out_done) DONE_ext <= 0; 
      case(state)
        state1: begin
          if(S_ready) begin
            S_flag <= 1;
            state <= state2;
          end 
        end
        state2: begin
          if(L_ready) begin
            S_flag <= 0;
            L_flag <= 1;
            state <= state3;
          end 
        end
        state3: begin
          if(roots_ready) begin
            L_flag <= 0;
            R_flag <= 1;
            state <= state4;
          end 
        end
        default: begin
          if(DONE) begin
            R_flag <= 0;
            state <= state1;
          end 
        end
      endcase
    end
  end

  wire [2:0] control;
  assign control = { R_flag, L_flag, S_flag };

  always @(*) begin
    add_pow1 <= 0;
    add_pow2 <= 0;
    add_pow3 <= 0;
    add_pow4 <= 0;
    add_dec1 <= 0;
    add_dec2 <= 0;
    add_dec3 <= 0;
    add_dec4 <= 0;
    pow1_BM_lamda <= 0;
    pow2_BM_lamda <= 0;
    dec1_BM_lamda <= 0;
