  end


  always @(posedge clk or posedge reset) begin
    if(reset) begin
      WE1 <= 0;
      WE2 <= 0;
      W_Add1 <= 0;
      W_Add2 <= 0;
      input_byte1 <= 0;
      input_byte2 <= 0;
    end else begin
      if(T_flag) begin
        if(WE_transport) begin
